public Map<String,String> getColorResources(){
  if (colorResources != null) {
    return colorResources;
  }
  ResourceBundle resourceBundle=ResourceBundle.getBundle(DEFAULT_COLOR_RESOURCE_PATH);
  Map<String,String> resources=new TreeMap<String,String>();
  this.initResources(resourceBundle,resources);
  try {
    this.initColorPluginResources(resources);
  } catch (ClassCastException | UnsupportedOperationException | IllegalArgumentException | NullPointerException | IndexOutOfBoundsException e) {
    throw new RuntimeException("Failed to initialize color plugin resources: " + e.getMessage(), e);
  }
  colorResources=resources;
  return resources;
}
